// P4, after k6. k6 reached this experiment and stopped because API_SET does not
// write AF Home key 0x9fa1. The settings writer is 0x60063431 (D0 key, D1 index,
// A1 value), the same writer the live profile source uses.
// Explanation: the zone type no longer comes from 0x9fa1. With AF-ON holding
// Single, writing 0x9fa1 to 1 must leave the Single record in place. Releasing
// and pressing again must still produce Single. Writing the profile byte to 2
// and pressing again must produce the Small record.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/exp_p4_k7.mjs om-emu
import { mkdirSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { runZone } from './zone_session_k1.mjs';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/exp_p4_k7.mjs om-emu\n');
  process.exit(2);
}
const OUT = resolve('work/out/edges-k7.jsonl');
const lines = [];
const emit = (row) => {
  lines.push(JSON.stringify(row));
  console.log(JSON.stringify(row));
  mkdirSync(resolve('work/out'), { recursive: true });
  writeFileSync(OUT, lines.join('\n') + '\n');
};
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const SINGLE = [0x0e, 0x02, 0x00, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00];
const SMALL = [0x0e, 0x02, 0x03, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00];
const HALF = [0x0e, 0x02, 0x03, 0x00, 0x03, 0x00, 0x03, 0x00, 0x00, 0x00];
let API_SET = 0;

async function bindApi() {
  const { A } = await import(pathToFileURL(resolve(checkout, 'emu/src/fw/model.mjs')).href);
  API_SET = A(0x50ac4afe);
}
function writeSetting(ctx, key, index, value) {
  return ctx.l.call(ctx.native(0x60063431), { d0: key, d1: index, a0: 0, a1: value }, null, null, 200000).d0 >>> 0;
}
function readSetting(ctx, key, index) {
  return ctx.l.call(ctx.native(0x60063380), { d0: key, d1: index, a0: 0 }, null, null, 200000).d0 & 0xffff;
}

emit({
  experiment: 'p4',
  record: 'explanation',
  text: 'The zone type no longer comes from AF Home 0x9fa1. Set the row to Single and hold AF-ON. Write 0x9fa1 index 0 to 1 through the settings writer 0x60063431. The held target must stay the Single record. Release and press again: still Single. Then set the profile byte to 2 and press: the target must be the Small record. Half-press cells other than that one 0x9fa1 write stay put.',
});

try {
  const result = await runZone({
    checkout,
    outPath: 'work/out/session-k7-p4.jsonl',
    tag: 'edge-k7-p4',
    candidate: true,
    help: true,
    rowLabel: true,
    overlayCsv: 'work/out/overlay-changed-bytes.csv',
    fatalShots: true,
    explanation: 'P4 isolates the profile byte from 0x9fa1. Role: behaviour.',
    change: 'profile source swap, plus one AF Home write used only as the negative control',
    async drive(ctx) {
      await bindApi();
      ctx.bringUp();
      ctx.s.switch_input('lever', 1);
      ctx.s.camapp.pump();
      ctx.idle(500);
      const argument = ctx.l.call(ctx.native(0x604050e5), { d0: 289, d1: 0 }, null, null, 200000).d0 >>> 0;
      ctx.l.call(API_SET, { d0: 289, d1: argument }, null, null, 200000);
      ctx.l.call(API_SET, { d0: 1712, d1: 0 }, null, null, 200000);
      ctx.idle(500);
      ctx.press('menu');
      for (let i = 0; i < 20; i++) ctx.press('left');
      ctx.press('down');
      ctx.press('down');
      ctx.press('ok');
      ctx.press('down');
      ctx.press('down');
      ctx.press('ok');
      ctx.press('right');
      ctx.shot('zone-1');
      ctx.press('ok');
      for (let i = 0; i < 8 && ctx.s.screen() !== 'shooting'; i++) ctx.press('menu');
      if (ctx.readByte(ctx.PROFILE) !== 1) throw new Error('profile ' + ctx.readByte(ctx.PROFILE));
      const homeBefore = readSetting(ctx, 0x9fa1, 0);
      const halfBefore = {
        k99a1: readSetting(ctx, 0x99a1, 0),
        k1dd1: readSetting(ctx, 0x1dd1, 0),
        k9a41: readSetting(ctx, 0x9a41, 0),
        k90a1: readSetting(ctx, 0x90a1, 0),
      };
      ctx.key('afon', 'down');
      ctx.idle(600);
      const held = { target: ctx.readTarget(), owner: ctx.readOwn()[4], profile: ctx.readByte(ctx.PROFILE) };
      emit({ experiment: 'p4', phase: 'held-single', held, homeBefore, halfBefore });
      if (!same(held.target, SINGLE) || held.owner !== 2) throw new Error('held single');
      const wrote = writeSetting(ctx, 0x9fa1, 0, 1);
      ctx.idle(200);
      const afterWrite = { target: ctx.readTarget(), home: readSetting(ctx, 0x9fa1, 0), wrote };
      emit({ experiment: 'p4', phase: 'after-9fa1-write', afterWrite });
      if (afterWrite.home !== 1) throw new Error('0x9fa1 did not change: ' + afterWrite.home);
      if (!same(afterWrite.target, SINGLE)) throw new Error('held target followed 0x9fa1');
      ctx.key('afon', 'up');
      ctx.idle(600);
      const released = { target: ctx.readTarget(), owner: ctx.readOwn()[4] };
      emit({ experiment: 'p4', phase: 'released', released });
      if (!same(released.target, HALF) || released.owner !== 0) throw new Error('release restore');
      ctx.key('afon', 'down');
      ctx.idle(600);
      const again = { target: ctx.readTarget(), owner: ctx.readOwn()[4], profile: ctx.readByte(ctx.PROFILE) };
      emit({ experiment: 'p4', phase: 'pressed-again', again });
      if (!same(again.target, SINGLE) || again.profile !== 1) throw new Error('press still follows 0x9fa1');
      ctx.key('afon', 'up');
      ctx.idle(300);
      ctx.l.call(ctx.native(0x6041937f), { d0: 0x3d6f, d1: 2 }, null, null, 200000);
      if (ctx.readByte(ctx.PROFILE) !== 2) throw new Error('profile byte');
      ctx.key('afon', 'down');
      ctx.idle(600);
      const small = { target: ctx.readTarget(), owner: ctx.readOwn()[4], profile: ctx.readByte(ctx.PROFILE) };
      emit({ experiment: 'p4', phase: 'profile-2', small });
      if (!same(small.target, SMALL) || small.owner !== 2) throw new Error('profile byte did not steer the target');
      const halfAfter = {
        k99a1: readSetting(ctx, 0x99a1, 0),
        k1dd1: readSetting(ctx, 0x1dd1, 0),
        k9a41: readSetting(ctx, 0x9a41, 0),
        k90a1: readSetting(ctx, 0x90a1, 0),
      };
      emit({ experiment: 'p4', phase: 'half-cells', halfBefore, halfAfter, home: readSetting(ctx, 0x9fa1, 0) });
      if (!same(halfBefore, halfAfter)) throw new Error('half-press cells moved');
      ctx.key('afon', 'up');
      ctx.idle(300);
    },
  });
  if (!result.ok) throw new Error(result.failed);
  emit({ record: 'done', ok: true });
} catch (e) {
  emit({ record: 'done', ok: false, error: String(e && e.stack ? e.stack : e) });
  process.exitCode = 1;
}
